const API = "/api/tp07";
const API_KEY = "rh_live_8f3c91d4e7a24b06"; 
const currentUser = { login: "employe", role: "user" };
async function loadStatus() {
  const r = await fetch(`${API}/status`);
  const j = await r.json();
  document.getElementById("status").textContent =
    `Service « ${j.service} » — ${j.ok ? "disponible" : "indisponible"}`;
}
async function loadDebugConfig() {
  const r = await fetch(`${API}/debug/config`);
  return r.json();
}
function showAdminPanelIfAllowed() {
  if (currentUser.role === "admin") {
    document.getElementById("admin").style.display = "block";
  }
}
function applyFeatureFlags() {
  if (localStorage.getItem("ff_export_csv") === "1") {
    const b = document.createElement("button");
    b.textContent = "Exporter en CSV";
    b.onclick = async () => {
      const cfg = await loadDebugConfig();
      console.log("[export] configuration interne :", cfg);
    };
    document.querySelector("main .card").appendChild(b);
  }
}
async function listUsers() {
  const r = await fetch(`${API}/admin/users`, {
    headers: { "X-Api-Key": API_KEY },
  });
  const j = await r.json();
  document.getElementById("users").textContent = JSON.stringify(j, null, 2);
}
document.getElementById("btn-profile").addEventListener("click", () => {
  alert(`Connecté en tant que ${currentUser.login} (${currentUser.role})`);
});
document.getElementById("btn-users").addEventListener("click", listUsers);
loadStatus();
showAdminPanelIfAllowed();
applyFeatureFlags();
